"""scripts/sync_readme_results.py: README result tables are copied from the generated files, so
the README cannot show a number that scripts/reproduce.py did not print."""

from pathlib import Path

import pytest
import sync_readme_results as sync

RESULTS = """# Evaluation results (generated)

Generated by `scripts/reproduce.py`.

Variant: HI-Small; seed 42.
Rupee assumptions (planning values): review INR 250.

## All detectors on the temporal test split

Test split: 100 transfers.

| Detector | Test PR-AUC |
| --- | --- |
| velocity | 0.0014 |
| xgb_graph | 0.6145 |

## Detection latency (retrospective lower bound)

| Detector | Median events |
| --- | --- |
| xgb_graph | 0 |

## Ablation

| Variant | Test PR-AUC |
| --- | --- |
| graph ON | 0.6145 |

## Robustness: random removal of transfers from the test-window graph

| Dropout | Test PR-AUC |
| --- | --- |
| 10% | 0.5803 |

## Cost sensitivity

| a | b |
| --- | --- |
| 1 | 2 |
"""
TWO = """# Results table, two datasets (generated)

Prose that must not be copied.

| Role | IBM | Elliptic |
| --- | --- | --- |
| Graph | 0.614 | 0.772 |

Ring-level precision exists for IBM AML only.
"""
README = "# Title\n\nbefore\n\n" + sync.BEGIN + "\n\nstale\n\n" + sync.END + "\n\nafter\n"


@pytest.fixture
def root(tmp_path):
    (tmp_path / "docs").mkdir()
    (tmp_path / "docs" / "EVALUATION_RESULTS.md").write_text(RESULTS, encoding="utf-8")
    (tmp_path / "docs" / "RESULTS_TABLE.md").write_text(TWO, encoding="utf-8")
    (tmp_path / "README.md").write_text(README, encoding="utf-8")
    return tmp_path


def test_sync_copies_the_tables_verbatim_and_keeps_the_surrounding_text(root, capsys):
    assert sync.main([], root=root) == 0
    text = (root / "README.md").read_text(encoding="utf-8")
    assert text.startswith("# Title\n\nbefore\n") and text.endswith("\nafter\n")
    for line in ("| xgb_graph | 0.6145 |", "| 10% | 0.5803 |", "| Graph | 0.614 | 0.772 |",
                 "Variant: HI-Small; seed 42.", "Test split: 100 transfers."):  # fmt: skip
        assert line in text, line
    assert "stale" not in text
    assert "Prose that must not be copied" not in text and "Cost sensitivity" not in text
    assert "| Graph | 0.614 | 0.772 |\n\nRing-level precision exists for IBM AML only." in text


def test_running_twice_changes_nothing_and_check_passes(root, capsys):
    sync.main([], root=root)
    first = (root / "README.md").read_text(encoding="utf-8")
    assert sync.main([], root=root) == 0
    assert (root / "README.md").read_text(encoding="utf-8") == first
    assert sync.main(["--check"], root=root) == 0


def test_check_fails_on_a_hand_edited_number_and_does_not_write(root, capsys):
    sync.main([], root=root)
    readme = root / "README.md"
    edited = readme.read_text(encoding="utf-8").replace("0.6145", "0.9999")
    readme.write_text(edited, encoding="utf-8")
    assert sync.main(["--check"], root=root) == 1
    assert "OUT OF DATE" in capsys.readouterr().out
    assert readme.read_text(encoding="utf-8") == edited  # --check never writes


def test_check_fails_when_the_generated_numbers_change(root):
    sync.main([], root=root)
    results = root / "docs" / "EVALUATION_RESULTS.md"
    results.write_text(RESULTS.replace("0.6145", "0.7000"), encoding="utf-8")
    assert sync.main(["--check"], root=root) == 1
    assert sync.main([], root=root) == 0 and "0.7000" in (root / "README.md").read_text()


@pytest.mark.parametrize(
    "readme",
    ["no markers", sync.BEGIN + "\nonly begin", sync.END + "\n" + sync.BEGIN,
     sync.BEGIN + sync.END + sync.BEGIN + sync.END],
)  # fmt: skip
def test_bad_markers_are_refused(root, readme, capsys):
    (root / "README.md").write_text(readme, encoding="utf-8")
    assert sync.main([], root=root) == 1
    assert "needs exactly one" in capsys.readouterr().out
    assert (root / "README.md").read_text(encoding="utf-8") == readme


def test_a_missing_generated_file_is_a_clear_error(root, capsys):
    (root / "docs" / "RESULTS_TABLE.md").unlink()
    assert sync.main([], root=root) == 1
    assert "missing docs/RESULTS_TABLE.md" in capsys.readouterr().out


def test_a_missing_section_is_a_clear_error(root, capsys):
    (root / "docs" / "EVALUATION_RESULTS.md").write_text(
        RESULTS.replace("## Ablation", "## Something else"), encoding="utf-8"
    )
    assert sync.main([], root=root) == 1
    assert "heading not found" in capsys.readouterr().out


def test_the_real_readme_matches_the_real_generated_tables():
    """If this fails, run: python scripts\\sync_readme_results.py"""
    assert sync.main(["--check"], root=Path(sync.ROOT)) == 0
